package com.justjava.humanresource.employeeexit.service; import com.justjava.humanresource.approval.model.ApproverRef; import com.justjava.humanresource.approval.service.ApprovalRouteResolverFactory; import com.justjava.humanresource.employeeexit.entity.EmployeeExitCase; import com.justjava.humanresource.hr.repository.EmployeeRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class ExitApprovalRouteService {private final ExitApprovalContextFactory contexts;private final ApprovalRouteResolverFactory factory;private final EmployeeRepository employees;private final EmployeeExitActivityService activity;public List<ApproverRef> resolve(EmployeeExitCase x){List<ApproverRef> route;try{var c=contexts.create(x);route=factory.getResolver(c).resolveApprovers(c);}catch(IllegalStateException ex){route=List.of();}if(route.isEmpty()){route=employees.findActiveEmployeesInGroup("humanResource").stream().map(e->ApproverRef.builder().employeeId(e.getId()).level(1).build()).toList();if(route.isEmpty())throw new IllegalStateException("No exit approver or HR fallback is configured.");activity.record(x.getId(),"APPROVAL_FALLBACK","No configured exit route; active HR employees were selected",null,null);}return route;}}
